function results(vars, bindings) {
    return JSON.stringify({ head: { vars }, results: { bindings } });
}

test.beforeAll(async () => {
    if (baseUrl || !fs.existsSync(BUNDLE)) return;
    server = http.createServer((request, response) => {
        const url = new URL(request.url || '/', 'http://localhost');
        if (url.pathname === '/collections.html') {
            response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' }).end(MOUNT_PAGE);
            return;
        }
        const file = path.normalize(path.join(FRONTEND, url.pathname.replace(/^\/rdf4j-workbench\//, '')));
        if (!url.pathname.startsWith('/rdf4j-workbench/') || !file.startsWith(FRONTEND + path.sep)
                || !fs.existsSync(file) || !fs.statSync(file).isFile()) {
            response.writeHead(404).end();
            return;
        }
        response.writeHead(200, { 'Content-Type': CONTENT_TYPES[path.extname(file)] || 'application/octet-stream' });
        fs.createReadStream(file).pipe(response);
    });
    await new Promise((resolve) => server.listen(0, '127.0.0.1', () => resolve(undefined)));
    baseUrl = `http://127.0.0.1:${server.address().port}/collections.html`;
});

test.afterAll(async () => {
    if (server) await new Promise((resolve) => server.close(() => resolve(undefined)));
});

async function openGraph(page, bindings = complete) {
    test.skip(!baseUrl, 'build the Workbench front end first (npm run build in tools/workbench)');
    const queries = [];
    const pageErrors = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));
    const origin = new URL(baseUrl).origin;
    const graphPath = `/rdf4j-workbench/repositories/${encodeURIComponent(REPOSITORY_ID)}/graph`;
    await page.route((url) => url.origin === origin && url.pathname.startsWith('/rdf4j-workbench/repositories/'), async (route) => {
        const request = route.request();
        const headers = { 'X-Workbench-Server-Identity': SERVER_IDENTITY, 'Cache-Control': 'no-store' };
        let body = results([], []);
        if (request.method() === 'POST' && new URL(request.url()).pathname === graphPath) {
            const query = request.postData() || '';
            queries.push(query);
            if (query === DEFAULT_QUERY) {
                body = results(['source', 'predicate', 'target'], bindings);
            } else if (/SELECT\s+(?:DISTINCT\s+)?\?source\s+\?predicate\s+\?target\b/i.test(query)
                    && query.includes('<_:pending-tail>')) {
                body = results(['source', 'predicate', 'target'], continuation);
            } else if (query.includes('SELECT DISTINCT ?resource ?labelProperty ?label')) {
                body = results(['resource', 'labelProperty', 'label'], labels.map((row) => ({
                    resource: row.source, labelProperty: row.predicate, label: row.target
                })));
            }
        }
        await route.fulfill({ status: 200, headers: { ...headers, 'Content-Type': 'application/sparql-results+json' }, body });
    });
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(`${baseUrl}?repository=${encodeURIComponent(REPOSITORY_ID)}`);
    await page.getByRole('button', { name: 'Load 100 statements', exact: true }).click();
    await expect(page.locator('.graph-node').first()).toBeAttached({ timeout: 30000 });
    return { queries, pageErrors };
}

const node = (page, id) => page.locator(`.graph-node[data-node-id="${id}"]`);
const card = (page) => node(page, '<_:members-1>');
async function inspect(page, id) {
    await node(page, id).focus();
    await node(page, id).press('Enter');
    await expect(page.locator('.node-details')).toBeVisible();
    return page.locator('.node-details');
}

async function download(page, label) {
    const explorer = page.locator('.graph-explorer');
    await explorer.locator('summary[aria-label="Open workspace tools"]').click();
    const [file] = await Promise.all([
        page.waitForEvent('download'),
        explorer.getByRole('button', { name: label, exact: true }).click()
    ]);
    const chunks = [];
    for await (const chunk of await file.createReadStream()) chunks.push(chunk);
    return Buffer.concat(chunks).toString('utf8');
}

test('collection cards retain literal values and repeated resource positions with Values off', async ({ page }) => {
    const { pageErrors } = await openGraph(page);
    await expect(card(page)).toHaveClass(/\bcollection\b/);
    await expect(card(page)).toContainText('3 items');
    await expect(card(page).locator('.collection-member')).toHaveCount(3);
    await expect(card(page).locator('[data-collection-index="1"]')).toHaveAttribute('data-member-id', `${EX}alice`);
    await expect(card(page).locator('[data-collection-index="3"]')).toHaveAttribute('data-member-id', `${EX}alice`);
    await expect(card(page).locator('[data-collection-index="2"]')).toContainText('second');
    await expect(node(page, '<_:members-2>')).toHaveCount(0);
    await expect(node(page, '<_:members-3>')).toHaveCount(0);
    await expect(page.locator('.graph-node.literal')).toHaveCount(0);
    expect(pageErrors).toEqual([]);
});

test('selecting a repeated member opens the existing resource rather than the list cell', async ({ page }) => {
    const { pageErrors } = await openGraph(page);
    await expect(card(page).locator('[data-collection-index="3"]')).toBeAttached();
    await card(page).locator('[data-collection-index="3"]').click();
    const details = page.locator('.node-details');
    await expect(details).toBeVisible();
    await expect(details).toContainText('Alice');
    await expect(details).toContainText(`${EX}alice`);
    await expect(node(page, `${EX}alice`)).toHaveCount(1);
    await expect(card(page)).toHaveClass(/\bcollection\b/);
    expect(pageErrors).toEqual([]);
});

test('RDF structure toggles independently of Turtle export and SVG includes the collection', async ({ page }) => {
    await openGraph(page);
    await expect(card(page)).toHaveClass(/\bcollection\b/);
    const compactTurtle = await download(page, 'Download Turtle');
    expect(compactTurtle.match(/rdf:first/g)).toHaveLength(3);
    expect(compactTurtle.match(/rdf:rest/g)).toHaveLength(3);
    const compactSvg = await download(page, 'Download SVG image');
    expect(compactSvg).toContain('3 items');
    expect(compactSvg).toContain('second');

    const details = await inspect(page, '<_:members-1>');
    await details.getByRole('button', { name: 'Show RDF structure', exact: true }).click();
    await expect(card(page)).not.toHaveClass(/\bcollection\b/);
    await expect(node(page, '<_:members-2>')).toBeAttached();
    await expect(node(page, '<_:members-3>')).toBeAttached();
    expect(await download(page, 'Download Turtle')).toBe(compactTurtle);
    await details.getByRole('button', { name: 'Show collection', exact: true }).click();
    await expect(card(page)).toHaveClass(/\bcollection\b/);
    await expect(node(page, '<_:members-2>')).toHaveCount(0);
});

test('showing one list spine leaves a second list compact', async ({ page }) => {
    await openGraph(page, twoLists);
    await expect(card(page)).toHaveClass(/\bcollection\b/);
    const otherList = node(page, '<_:projects-1>');
    await expect(otherList).toHaveClass(/\bcollection\b/);
    const details = await inspect(page, '<_:members-1>');
    await details.getByRole('button', { name: 'Show RDF structure', exact: true }).click();
    await expect(card(page)).not.toHaveClass(/\bcollection\b/);
    await expect(node(page, '<_:members-2>')).toBeAttached();
    await expect(otherList).toHaveClass(/\bcollection\b/);
    await expect(otherList).toContainText('1 item');
});

test('member connections aggregate duplicate positions without duplicating resource nodes', async ({ page }) => {
    await openGraph(page);
    const details = await inspect(page, '<_:members-1>');
    await details.getByRole('button', { name: 'Show member connections', exact: true }).click();
    const connections = page.locator('.edge.collection-membership');
    await expect(connections).toHaveCount(2);
    await expect(connections.locator('title').filter({ hasText: /positions 1, 3/ })).toHaveCount(1);
    await expect(node(page, `${EX}alice`)).toHaveCount(1);
    await details.getByRole('button', { name: 'Hide member connections', exact: true }).click();
    await expect(connections).toHaveCount(0);
    await expect(card(page)).toHaveClass(/\bcollection\b/);
});

test('partial lists load continuation by certified tail identity before acquiring an exact count', async ({ page }) => {
    const { queries, pageErrors } = await openGraph(page, partial);
    const details = await inspect(page, '<_:pending-head>');
    await expect(details).toContainText(/incomplete|continuation unknown/i);
    await details.getByRole('button', { name: 'Load continuation', exact: true }).click();
    await expect.poll(() => queries.some((query) => query.includes('<_:pending-tail>')
        && /SELECT\s+(?:DISTINCT\s+)?\?source\s+\?predicate\s+\?target\b/i.test(query))).toBe(true);
    await expect(node(page, '<_:pending-head>')).toHaveClass(/\bcollection\b/);
    await expect(node(page, '<_:pending-head>')).toContainText('2 items');
    await expect(node(page, '<_:pending-head>')).toContainText('last');
    expect(pageErrors).toEqual([]);
});

test('shared tails remain identifiable and neither incoming list silently absorbs them', async ({ page }) => {
    const { pageErrors } = await openGraph(page, sharedTail);
    await expect(node(page, '<_:shared-head-1>')).toBeAttached();
    await expect(node(page, '<_:shared-head-2>')).toBeAttached();
    await expect(node(page, '<_:shared-tail>')).toBeAttached();
    await expect(node(page, '<_:shared-head-1>')).not.toHaveClass(/\bcollection\b/);
    await expect(node(page, '<_:shared-head-2>')).not.toHaveClass(/\bcollection\b/);
    const details = await inspect(page, '<_:shared-head-1>');
    await expect(details).toContainText(/shared|referenc/i);
    expect(pageErrors).toEqual([]);
});
